mapper.select:
SELECT id, folder_id, item_type, target_id, knowledge_id, blog_id, sort, created_at, updated_at
FROM sys_favorite_item
WHERE folder_id = #{folderId}
  AND item_type = #{itemType}
  AND target_id = #{targetId}
  AND (deleted IS NULL OR deleted = 0)
LIMIT 1

SELECT DISTINCT f.id, f.name, f.description, f.user_id, f.is_public, f.cover_image,
       f.item_count, f.view_count, f.created_at, f.updated_at
FROM sys_favorite_folder f
INNER JOIN sys_favorite_item i ON f.id = i.folder_id
WHERE f.user_id = #{userId}
  AND i.item_type = #{itemType}
  AND i.target_id = #{targetId}
  AND (f.deleted IS NULL OR f.deleted = 0)
  AND (i.deleted IS NULL OR i.deleted = 0)
ORDER BY f.created_at DESC
